// Ann is Bob's parent, and Bob is Cara's parent. Recursive backward rules
// answer who Ann's descendants are: Bob and Cara. log:query selects those
// answers, illustrating N3 rules compiled to ordinary eyemind clauses.
//
// Compiled from examples/n3-family.n3 by eyemind: eyemind --program examples/n3-family.n3.
// The generated program below runs directly in eyemind and the playground.

// Generated by eyemind from examples/n3-family.n3, Notation3.
// Each N3 triple is rdf(Subject, Predicate, Object). Without a log:query
// the conclusions are the triples the forward rules derive.
fact(rdf(iri("https://example.org/family#ann"), iri("https://example.org/family#parent"), iri("https://example.org/family#bob")))
fact(rdf(iri("https://example.org/family#bob"), iri("https://example.org/family#parent"), iri("https://example.org/family#cara")))
implied_by(rdf(Person, iri("https://example.org/family#ancestor"), Descendant), rdf(Person, iri("https://example.org/family#parent"), Descendant))
implied_by(rdf(Person, iri("https://example.org/family#ancestor"), Descendant), [rdf(Person, iri("https://example.org/family#parent"), Child), rdf(Child, iri("https://example.org/family#ancestor"), Descendant)])
implies(rdf(iri("https://example.org/family#ann"), iri("https://example.org/family#ancestor"), Who), result(iri("https://example.org/family#ann"), iri("https://example.org/family#ancestor"), Who))
query(result(S, P, O))
